// Presentation layer: preserves the reviewed ontology and shared grade projection.
const repo='https://github.com/GarageThermonuclearLaboratories/Minerva';
let selectedId=null, graphFocus=standardId, graphDepth=1, receiptOrigin=null;
const statuses={SOURCE:'Source-backed wording or structure; applicability is separate.',PARSED:'Project interpretation with its source derivation preserved.',NORMALIZED:'Alignment into a shared representation.',INFERRED:'A derived claim requiring an explicit method and evidence.',PROVISIONAL:'Tentative support or unresolved applicability.',CONTESTED:'An unresolved substantive dispute.',REJECTED:'Excluded with a recorded reason.',UNREVIEWED:'Evidence or a question awaiting review.',UNMAPPED:'No modeled expectation here yet; not evidence of absence.'};
const badge=s=>`<span class="tag ${s.toLowerCase()}" title="${esc(statuses[s]||s)}">${esc(s)}</span>`;
const gitPath=p=>`${repo}/blob/${release.research_commit||'main'}/${p}`;
const originalRender=render, originalReceipt=showReceipt;
titles.atlas=['What is New York asking students to learn?','Wildcats is building a source-traced ontology of New York State K–12 educational expectations. Minerva makes that formal structure human to explore.'];
titles.journey=['Across grades','Developmental links need evidence. Only one Grade 7 mathematics family is mapped so far.'];
titles.curriculum=['Inside the standards','Inspect the source’s own categories, then follow each standard into its parsed expectations.'];

function closeReceipt(restore=true){
  $('#receipt').hidden=true;$('#receipt-toggle').setAttribute('aria-expanded','false');
  if(restore&&receiptOrigin?.isConnected)receiptOrigin.focus();
}
function navigate(name){view=name;closeReceipt(false);render();$('#title').focus();window.scrollTo({top:0,behavior:'smooth'});}
function studentLens(id){
  const n=node(id),source=n?.derived_from||id;
  const edge=model.edges.find(e=>e.relation==='ASSIGNED_TO_GRADE'&&e.from===source);if(!edge)return;
  grade=Number(edge.to.split(':').pop());transition=false;navigate('wildcats');
  const target=document.querySelector(`#view [data-node="${id}"]`);
  if(target){target.classList.add('lens-target');target.focus();target.scrollIntoView({block:'center',behavior:'smooth'});}
}
showReceipt=function(id){
  if(!node(id))return;
  if(!$('#receipt').contains(document.activeElement))receiptOrigin=document.activeElement;
  selectedId=id;$('#receipt').hidden=false;originalReceipt(id);
  const n=node(id),edges=model.edges.filter(e=>e.from===id||e.to===id);
  const assignment=model.edges.some(e=>e.relation==='ASSIGNED_TO_GRADE'&&e.from===(n.derived_from||id));
  const body=$('#receipt-body');
  body.innerHTML=body.innerHTML.replace('SOURCE WORDING','WHAT NEW YORK SAID').replace('SOURCE STRUCTURE','SOURCE CATEGORY').replace('PROJECT INTERPRETATION','WHAT WAS PARSED').replace('No independent audit is claimed.','This field records the earlier review state. The subsequent M7 independent agent audit passed for this bounded trace; human review remains pending.');
  body.innerHTML=`<div class="receipt-actions"><button data-neighborhood="${esc(id)}">Explore neighborhood</button>${assignment?`<button data-lens="${esc(id)}">See this through a student</button>`:''}</div>`+body.innerHTML+
    `<h3>HOW IT WAS NORMALIZED</h3><p>Normalization has not started. No broader capability hierarchy or cross-subject equivalence is claimed.</p><h3>RECORDED RELATIONSHIPS</h3><p>These are source and parsing links. No inferred prerequisite or developmental chain is asserted.</p><ul class="edge-list">${edges.map(e=>`<li><span>${esc(node(e.from).label)} <b>${esc(e.relation)}</b> ${esc(node(e.to).label)}</span>${badge(e.status)}<small>${esc(e.source_locator)}</small></li>`).join('')||'<li>No incident relationships recorded.</li>'}</ul>
    <h3>ASSUMPTIONS AND UNRESOLVED ISSUES</h3><p>${model.canonical_assumptions.length} canonical assumptions recorded. No Johnson City choice has been invoked. Exact edition/cohort applicability and human review remain unresolved. Coherence semantics and source footnote 14 remain unreviewed.</p><p><a href="${gitPath('docs/monday-audit.md')}" target="_blank" rel="noopener">Independent audit scope and limits</a></p>`;
  $('#receipt-toggle').disabled=false;$('#receipt-toggle').setAttribute('aria-expanded','true');bindEvidence(body);$('#close-receipt').focus();
};
function neighborhood(focus,depth=1){
  const ids=new Set([focus]);
  for(let i=0;i<depth;i++){const previous=new Set(ids);for(const e of model.edges){if(previous.has(e.from)||previous.has(e.to)){if(ids.size<20)ids.add(e.from);if(ids.size<20)ids.add(e.to);}}}
  return {nodes:model.nodes.filter(n=>ids.has(n.id)),edges:model.edges.filter(e=>ids.has(e.from)&&ids.has(e.to))};
}
function wrapLabel(label){const lines=[''];for(const w of label.split(' ')){const i=lines.length-1;if((lines[i]+' '+w).trim().length>25&&lines[i])lines.push(w);else lines[i]=(lines[i]+' '+w).trim();}return lines;}
function graphHtml(){
  const graph=neighborhood(graphFocus,graphDepth),others=graph.nodes.filter(n=>n.id!==graphFocus);
  const height=Math.max(380,Math.ceil(others.length/2)*115+50),positions=new Map([[graphFocus,{x:355,y:height/2-46}]]);
  others.forEach((n,i)=>{const side=i%2,rank=Math.floor(i/2),count=Math.ceil((others.length-side)/2);positions.set(n.id,{x:side?685:25,y:(height-count*115)/2+rank*115+12});});
  const lines=graph.edges.map(e=>{const a=positions.get(e.from),b=positions.get(e.to);return `<path data-edge="${esc(e.id)}" class="graph-edge ${e.status.toLowerCase()}" d="M${a.x+125},${a.y+46} L${b.x+125},${b.y+46}"><title>${esc(node(e.from).label+' — '+e.relation+' → '+node(e.to).label+' ['+e.status+']')}</title></path>`;}).join('');
  return `<div class="section-head"><h2>Local ontology neighborhood</h2><span>${graph.nodes.length} nodes · ${graph.edges.length} links</span></div><p class="muted">Centered on ${esc(node(graphFocus).label)}. Lines are recorded relationships, not a timeline. Exact directions and predicates are listed below.</p><div class="graph-toolbar"><button id="graph-expand" ${graphDepth===2?'disabled':''}>${graphDepth===2?'Two steps shown':'Expand one step'}</button><button id="graph-reset">Reset to NY-7.RP.2</button><span>Maximum 20 nodes · scroll sideways on small screens</span></div>
  <div class="graph-scroll" tabindex="0" role="region" aria-label="Scrollable local ontology graph"><svg class="ontology-graph" viewBox="0 0 960 ${height}" aria-label="Source and parsed nodes connected by recorded relationships">${lines}${graph.nodes.map(n=>{const p=positions.get(n.id);return `<g class="graph-node ${n.status.toLowerCase()} ${n.id===graphFocus?'graph-center':''}" data-node="${esc(n.id)}" role="button" tabindex="0" aria-label="${esc(n.label+'; '+n.status+'; open Receipt')}" transform="translate(${p.x},${p.y})"><rect width="250" height="92" rx="3"/><text class="graph-status" x="14" y="21">${esc(n.type.toUpperCase())} · ${esc(n.status)}</text><text x="14" y="44">${wrapLabel(n.label).slice(0,3).map((l,i)=>`<tspan x="14" dy="${i?18:0}">${esc(l)}</tspan>`).join('')}</text><title>${esc(n.label)}</title></g>`;}).join('')}</svg></div>
  <details class="graph-relations"><summary>Read ${graph.edges.length} exact relationships</summary><ul class="edge-list">${graph.edges.map(e=>`<li data-edge-id="${esc(e.id)}"><button data-node="${esc(e.from)}">${esc(node(e.from).label)}</button><b>${esc(e.relation)}</b><button data-node="${esc(e.to)}">${esc(node(e.to).label)}</button>${badge(e.status)}</li>`).join('')}</ul></details>`;
}
function methodology(){return `<details class="methodology"><summary>How to read Minerva · evidence, uncertainty, and the local reference</summary><h3>Source → Structure → Receipt</h3><p>Wildcats is the educational ontology. Minerva is Garage Thermonuclear Laboratories’ humane interface to formal ontologies: a way to inspect objects, relationships, and their reasons for existing.</p><p>“Known” is not a blanket truth label. A source can be inspected while its edition’s applicability remains unresolved. Derivation, claim disposition, review, and map coverage answer different questions.</p><div class="status-legend">${Object.entries(statuses).map(([s,d])=>`<div>${badge(s)}<p>${esc(d)}</p></div>`).join('')}</div><h3>Two districts, different jobs</h3><p>Garage City School District is the fictional public-facing research model. Local reference district: Johnson City Central School District. Consulted only where New York State leaves a canonical implementation question unresolved. No Johnson City assumption has been used in the current trace.</p><p>Matthew and Eva are fictional reference students, not records of real children, demographic simulations, or assessments. Their identities do not change the shared expected graph.</p><p>Standards do not automatically establish an individual legal obligation, a measurable assessment, mastery, or a prerequisite. No Garage-internal ontology is used before the v0.1 freeze.</p><a href="${gitPath('docs/foundation-specification.md')}" target="_blank" rel="noopener">Foundation specification</a></details>`;}
function atlasHtml(){return `<div class="section-head"><h2>First mapped region</h2><span>Grade 7 · Mathematics</span></div><div class="trace-preview"><div class="trace-source">${row(standardId,node(standardId).original_text)}</div><div class="trace-connector">Heading decomposed into two actions · PARSED</div><div class="trace-parsed">${row('wc:expectation:recognize-proportional','DERIVED_FROM NY-7.RP.2')}${row('wc:expectation:represent-proportional','DERIVED_FROM NY-7.RP.2')}</div></div><p class="muted">1 parent standard · 4 source subparts · 6 parsed expectations. Overlapping levels of detail, not six independent standards.</p><div class="project-thesis"><p>The atlas reconstructs what students are expected to learn. As it grows, reviewed connections may reveal what expectations build upon and how ideas relate across grades and subjects—structures difficult to see in the original documents, and questions those documents were never organized to answer.</p><p>Wildcats is Minerva’s first proving ground. Today’s bounded trace demonstrates source → structure → Receipt; developmental and cross-disciplinary discovery are goals, with <b>0 published findings</b> so far.</p><div class="research-path" aria-label="Research ambition"><span>NYSED documents</span><span>Source-traced ontology</span><span>Structural analysis</span><span>New questions</span><span>Evidence-backed findings</span></div></div>${graphHtml()}${methodology()}`;}
const statusWords={'pending-full-document':'Pending','two-full-documents-acquired':'2 PDFs','not-started':'Not started','one-parent-four-subparts-six-expectations; bounded-agent-review':'Partial','source-and-parse-links-only':'Source / parse','references-hashes-and-reviewed-wording':'Bounded checks','pending':'Pending'};
function workbenchHtml(){
  const keys=['acquisition','parsing','normalization','relationships','validation','human_review'];
  const families=[...corpus.families].sort((a,b)=>(b.label==='Mathematics')-(a.label==='Mathematics'));
  return `<div class="metric-grid">${[[manifest.sources.length,'source records'],[manifest.sources.filter(s=>s.acquisition_status==='full-document-acquired').length,'PDFs acquired'],[model.nodes.filter(n=>n.type==='Expectation').length,'parsed expectations']].map(([v,l])=>`<div class="metric"><b>${v}</b><span>${l}</span></div>`).join('')}</div><div class="section-head"><h2>Content-area coverage</h2><span>12 areas · not a document denominator</span></div><p>Mathematics has begun. The other eleven areas await full-document acquisition. Human review is pending throughout.</p><p class="muted">Scroll sideways for every stage. Expand a content area for exact recorded statuses.</p><div class="table-scroll" tabindex="0" role="region" aria-label="Content-area status matrix"><table class="coverage-table"><thead><tr><th scope="col">Content area</th>${['Acquire','Parse','Normalize','Relationships','Validate','Human review'].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${families.map((f,i)=>`<tr class="${f.label==='Mathematics'?'started':''}"><th scope="row"><button class="matrix-toggle" data-family="${i}" aria-expanded="false" aria-controls="family-${i}"><span aria-hidden="true">+</span> ${esc(f.label)}</button></th>${keys.map(k=>`<td title="${esc(f[k])}">${esc(statusWords[f[k]]||f[k])}</td>`).join('')}</tr><tr id="family-${i}" hidden><td colspan="7"><dl class="matrix-detail">${keys.map(k=>`<dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(f[k])}</dd>`).join('')}</dl><p>Inventory source: ${esc(f.source_id)}. Checks are not full semantic review.</p></td></tr>`).join('')}</tbody></table></div><details class="methodology"><summary>Evidence acquired and provisional dates</summary><p>Two uploaded mathematics PDFs are archived with hashes. All 184 pages have text extracts; selected pages received visual inspection. The bounded NY-7.RP.2 trace passed independent agent review. This is not full-corpus semantic review.</p><p>${badge('PROVISIONAL')} Prior search excerpts suggested September 2017 adoption, September 2022 implementation, and spring 2023 aligned assessments. Exact supporting excerpts and section locators were not preserved. Full-page verification is pending. The uploaded full document identifies an update in June 2019; edition applicability remains unresolved.</p><a href="${gitPath('docs/source-inventory.md')}" target="_blank" rel="noopener">Full source inventory</a></details>${methodology()}`;
}
function logHtml(){return `<article class="log-entry" id="log-current"><time datetime="2026-09-29">Tuesday, September 29, 2026</time><h2>v0.0.4 · Monday foundation and public interface</h2><p>15 nodes · 22 relationships · 6 parsed expectations · 0 findings. The bounded trace and shared K–12 scaffold passed the M7 independent agent audit after repairs. This subsequent interface pass exposes the local graph, contextual student lens, expandable Receipts, and coverage matrix; it adds no ontology claims.</p><p>Five grade predicates were narrowed to ASSIGNED_TO_GRADE: placement is not an attainment deadline. Timeline observations were downgraded to PROVISIONAL because durable excerpts were not preserved. Six Coherence arrows remain observations, not prerequisites.</p><p>Human review and exact edition/cohort applicability remain open. Interface verification is builder review, separate from the M7 audit.</p><p><a href="${gitPath('docs/monday-audit.md')}" target="_blank" rel="noopener">Independent audit</a> · <a href="${gitPath('docs/site-revision-0.0.4.md')}" target="_blank" rel="noopener">Interface revision record</a></p></article><article class="log-entry"><time datetime="2026-09-28">Monday, September 28, 2026</time><h2>v0.0.3 · Original documents acquired</h2><p>Two uploaded PDFs were archived and hashed; 184 pages extracted. Page 90 supports the parent and four subparts. The crosswalk is marked Draft and remains supporting evidence.</p><p>11 nodes · 14 edges · 2 parsed expectations · 0 findings.</p><a href="${gitPath('docs/primary-pdf-review.md')}" target="_blank" rel="noopener">Primary PDF review</a></article><article class="log-entry"><time datetime="2026-09-28">Monday, September 28, 2026</time><h2>v0.0.2 · Source review and corpus inventory</h2><p>Seven source records and twelve content areas were identified. PDF acquisition failed with HTTP 502. Only two heading expectations were parsed at this checkpoint.</p><p>The phrase “one verified standard” overstated search-excerpt evidence and was corrected. Timeline observations recorded here were later downgraded to PROVISIONAL during M7.</p><p>7 nodes · 6 edges · 0 findings.</p><a href="${gitPath('docs/source-review.md')}" target="_blank" rel="noopener">Source review and correction</a></article><article class="log-entry"><time datetime="2026-09-28">Monday, September 28, 2026</time><h2>v0.0.1 · Initial checkpoint</h2><p>One source heading entered the model with stable IDs, two parsed actions, six relationships, and inspectable Receipts. Matthew and Eva shared the expected projection.</p><p>7 nodes · 6 edges · 0 findings. An initial trace, not a complete standard review.</p><a href="${repo}/commit/647494729893aae73fd764bae9ff2742b260dbd2" target="_blank" rel="noopener">Initial research checkpoint</a></article><p><a href="${gitPath('docs/lab-log.md')}" target="_blank" rel="noopener">Full Lab Log and publication history</a></p>`;}
function bindEvidence(root){
  root.querySelectorAll('[data-node]').forEach(b=>{b.onclick=()=>showReceipt(b.dataset.node);if(b.tagName.toLowerCase()==='g')b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showReceipt(b.dataset.node);}};});
  root.querySelectorAll('[data-neighborhood]').forEach(b=>b.onclick=()=>{graphFocus=b.dataset.neighborhood;graphDepth=1;navigate('atlas');$('.graph-scroll').scrollIntoView({block:'center',behavior:'smooth'});});
  root.querySelectorAll('[data-lens]').forEach(b=>b.onclick=()=>studentLens(b.dataset.lens));
}
render=function(){
  originalRender();
  $('#release-label').textContent='v'+(model.release.match(/\d+\.\d+\.\d+/)?.[0]||model.release)+' · Monday checkpoint';
  $('#epistemic-notice').open=['atlas','wildcats'].includes(view);
  document.querySelectorAll('.rail button').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
  // Baseline is the published 0.0.3 record (11 nodes, 14 edges), not a live daily counter.
  $('#activity').innerHTML=`<button id="activity-log">Since v0.0.3 · +${model.nodes.length-11} nodes · +${model.edges.length-14} links · ${model.findings.length} findings <span>Lab Log</span></button>`;
  if(view==='atlas')$('#view').innerHTML=atlasHtml();
  if(view==='curriculum')$('#view').innerHTML=`<div class="section-head"><h2>Source categories</h2><span>NYSED wording</span></div>${row('wc:grade:7','Source grade placement')}${row('wc:subject:mathematics','NYSED subject')}${row('wc:domain:7-rp','NYSED domain')}<p class="muted">These are source labels. No normalized “Mathematical reasoning” capability family is asserted in this ontology.</p><div class="section-head"><h2>Parent and subparts</h2><span>Page 90</span></div>${[standardId,...'abcd'.split('').map(k=>standardId+k)].map(id=>row(id,node(id).original_text)+model.nodes.filter(n=>n.type==='Expectation'&&n.derived_from===id).map(n=>row(n.id,'Parsed from '+node(id).label)).join('')).join('')}`;
  if(view==='journey')$('#view').innerHTML=`<div class="territories"><div class="panel unmapped">${badge('UNMAPPED')}<h2>Earlier grades</h2><p>No earlier expectations modeled in this trace.</p></div><div class="panel mapped">${badge('SOURCE')}<h2>Grade 7 anchor</h2>${row(standardId,'Inspect the source-backed placement')}</div><div class="panel unmapped">${badge('UNMAPPED')}<h2>Later grades</h2><p>No later expectations modeled in this trace.</p></div></div><p>No connecting line is asserted between these territories. Grade order alone does not establish a developmental or prerequisite relationship.</p><details class="methodology"><summary>Six source Coherence observations · semantics unreviewed</summary>${badge('UNREVIEWED')}<p>These source arrows need target and semantic review before becoming ontology edges.</p><ul>${review.coherence_observations.map(x=>`<li>${esc(x.source_standard)} → ${esc(x.target_standard)}</li>`).join('')}</ul><a href="evidence/math-full/page-90.png" target="_blank" rel="noopener">Inspect the source page</a></details>`;
  if(view==='crossroads')$('#view').innerHTML=`<div class="section-head"><h2>Cross-disciplinary connections</h2><span>0 reviewed · 0 provisional</span></div><div class="panel unmapped">${badge('UNMAPPED')}<h2>No second subject mapped yet</h2><p>Similar words are not enough to establish equivalence. Each connection will need supporting nodes, a defined relationship, provenance, and review.</p></div>`;
  if(view==='wildcats'){
    const panel=$('.journey-panel');if(!transition&&!standardsForGrade(grade).length)panel.classList.add('unmapped');
    const map=`<div class="grade-map" aria-label="Thirteen grades and coverage">${Array.from({length:13},(_,g)=>`<button data-grade="${g}" class="${standardsForGrade(g).length?'mapped':'unmapped'} ${!transition&&grade===g?'selected':''}" aria-pressed="${!transition&&grade===g}" aria-label="${gradeLabel(g)}: ${standardsForGrade(g).length?'partially mapped':'unmapped'}"><b>${g===0?'K':g}</b><small>${standardsForGrade(g).length?'PARTIAL':'UNMAPPED'}</small></button>`).join('')}</div>`;
    panel.insertAdjacentHTML('beforebegin',map);
    document.querySelectorAll('[data-stage]').forEach(b=>{const s=journey.stages.find(s=>s.id===b.dataset.stage);if(s.coverage==='not-yet-mapped'){b.classList.add('unmapped');b.textContent+=' · Unmapped';}});
    document.querySelectorAll('#journey-grade option').forEach(o=>o.textContent+=' · '+(standardsForGrade(+o.value).length?'partially mapped':'unmapped'));
    $('#view').insertAdjacentHTML('beforeend','<p class="journey-context">Fictional reference students, not records of real children, demographic outcome simulations, or individual assessments.</p>');
    document.querySelectorAll('[data-grade]').forEach(b=>b.onclick=()=>{grade=+b.dataset.grade;transition=false;render();});
  }
  if(view==='workbench')$('#view').innerHTML=workbenchHtml();
  if(view==='findings')$('#view').insertAdjacentHTML('beforeend','<details class="methodology"><summary>What will qualify as a finding?</summary><p>A computed or analytically derived result with a claim, supporting nodes, ontology version, Git revision, method, epistemic status, review state, first-detected date, and last-validation date. Its evidence must open in the graph and Receipts. No finding is generated just to populate this page.</p></details>');
  if(view==='log')$('#view').innerHTML=logHtml();
  bindEvidence($('#view'));$('#activity-log').onclick=()=>navigate('log');
  document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{const expanded=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!expanded));$('#family-'+b.dataset.family).hidden=expanded;b.querySelector('span').textContent=expanded?'+':'−';});
  if($('#graph-expand'))$('#graph-expand').onclick=()=>{graphDepth=2;render();};
  if($('#graph-reset'))$('#graph-reset').onclick=()=>{graphFocus=standardId;graphDepth=1;render();};
};
document.querySelectorAll('.rail button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
$('#close-receipt').onclick=()=>closeReceipt();
$('#receipt-toggle').onclick=()=>{if(!$('#receipt').hidden)closeReceipt();else if(selectedId)showReceipt(selectedId);};
$('#expand-receipt').onclick=()=>{const expanded=$('#receipt').classList.toggle('expanded');$('#expand-receipt').textContent=expanded?'Reduce':'Expand';$('#expand-receipt').setAttribute('aria-pressed',String(expanded));};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#receipt').hidden)closeReceipt();});
// Also upgrade the first view if its data arrived before this deferred script.
if(model)render();
